package com.neighbormarket.ai;
import com.neighbormarket.config.SecurityConfig;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.context.TestPropertySource;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
@WebMvcTest(PricingController.class) @Import(SecurityConfig.class) @TestPropertySource(properties="app.allowed-origins=http://localhost") class PricingControllerSecurityTest {@Autowired MockMvc mvc;@MockBean PricingService service;@Test void unauthenticatedRequestIsRejected()throws Exception{mvc.perform(post("/api/ai/pricing").contentType("application/json").content("{\"tradeType\":\"FIXED_PRICE\"}")).andExpect(status().isUnauthorized());}}